import React, { useState, useEffect } from 'react';
import { FiBook, FiCalendar, FiMessageSquare, FiUsers, FiVideo, FiImage } from 'react-icons/fi';
import api from '../../services/api';
import AdminCard from '../common/AdminCard';

const AdminDashboard = () => {
  const [stats, setStats] = useState({
    courses: 0,
    events: 0,
    messages: 0,
    videos: 0,
    gallery: 0,
    users: 0,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      const [courses, events, messages, videos, gallery] = await Promise.all([
        api.get('/api/courses/'),
        api.get('/api/events/'),
        api.get('/api/contact/'),
        api.get('/api/videos/'),
        api.get('/api/gallery/'),
      ]);

      setStats({
        courses: courses.data.length || 0,
        events: events.data.length || 0,
        messages: messages.data.length || 0,
        videos: videos.data.length || 0,
        gallery: gallery.data.length || 0,
        users: 1,
      });
    } catch (error) {
      console.error('Error fetching stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const statsData = [
    { title: 'Total Courses', value: stats.courses, icon: FiBook, color: 'bg-blue-500' },
    { title: 'Upcoming Events', value: stats.events, icon: FiCalendar, color: 'bg-green-500' },
    { title: 'Messages', value: stats.messages, icon: FiMessageSquare, color: 'bg-yellow-500' },
    { title: 'Videos', value: stats.videos, icon: FiVideo, color: 'bg-purple-500' },
    { title: 'Gallery Images', value: stats.gallery, icon: FiImage, color: 'bg-pink-500' },
    { title: 'Admin Users', value: stats.users, icon: FiUsers, color: 'bg-indigo-500' },
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-900"></div>
      </div>
    );
  }

  return (
    <div>
      <h1 className="text-3xl font-bold text-blue-900 mb-8">Dashboard</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
        {statsData.map((stat, index) => (
          <AdminCard key={index} className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">{stat.title}</p>
                <p className="text-3xl font-bold text-blue-900 mt-1">{stat.value}</p>
              </div>
              <div className={`${stat.color} p-3 rounded-lg text-white`}>
                <stat.icon className="text-2xl" />
              </div>
            </div>
          </AdminCard>
        ))}
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <AdminCard className="p-6">
          <h3 className="font-bold text-blue-900 mb-2">📚 Quick Actions</h3>
          <div className="space-y-2">
            <button className="w-full text-left px-4 py-2 bg-gray-50 hover:bg-gray-100 rounded-lg transition">
              + Add New Course
            </button>
            <button className="w-full text-left px-4 py-2 bg-gray-50 hover:bg-gray-100 rounded-lg transition">
              + Create New Event
            </button>
            <button className="w-full text-left px-4 py-2 bg-gray-50 hover:bg-gray-100 rounded-lg transition">
              + Upload Gallery Image
            </button>
          </div>
        </AdminCard>

        <AdminCard className="p-6">
          <h3 className="font-bold text-blue-900 mb-2">📊 Recent Activity</h3>
          <div className="space-y-3">
            <div className="flex items-center space-x-3 text-sm">
              <span className="w-2 h-2 bg-green-500 rounded-full"></span>
              <span className="text-gray-600">No recent activity</span>
            </div>
          </div>
        </AdminCard>
      </div>
    </div>
  );
};

export default AdminDashboard;
